class PhanSo {
private:
    int tu;
    int mau;

public:
    // Constructor to initialize the fraction
    PhanSo(int t = 0, int m = 1) : tu(t), mau(m) {}

    // Function to input a fraction from user
    void nhap() {
        cout << "Nhap tu so: ";
        cin >> tu;
        cout << "Nhap mau so: ";
        cin >> mau;
    }

    // Function to display a fraction
    void xuat() const {
        if (mau == 0)
            cout << "Khong hop le!";
        else if (tu % mau == 0)
            cout << tu / mau;
        else if (abs(tu) > abs(mau))
            cout << tu / gcd(abs(tu), abs(mau)) << "/" << mau / gcd(abs(tu), abs(mau));
        else
            cout << tu << "/" << mau;
    }

private:
    // Helper function to calculate GCD of two numbers using Euclid's algorithm
    static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
};

